mapper.select:
SELECT o.id, o.order_no AS orderNo, o.sale_time AS saleTime, o.total_amount AS totalAmount, o.actual_amount AS actualAmount, o.pay_method AS payMethod, o.status, c.name AS customerName, c.phone AS customerPhone, d.name AS deptName, e.name AS operatorName FROM sale_order o LEFT JOIN customer c ON o.customer_id = c.id LEFT JOIN dept d ON o.dept_id = d.id LEFT JOIN employee e ON o.operator_id = e.id
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND c.name LIKE CONCAT('%', #{customerName}, '%')
AND c.phone LIKE CONCAT('%', #{customerPhone}, '%')
AND o.dept_id = #{deptId}
AND DATE(o.sale_time) >= #{startDate}
AND DATE(o.sale_time) <= #{endDate}
ORDER BY o.sale_time DESC
